import { ArrowDownRight, ArrowRight, BarChart3, BookOpenCheck, BriefcaseBusiness, Check, CheckCircle2, ChevronRight, CircleHelp, ClipboardCheck, Clock3, FileText, Gauge, History, Home, LockKeyhole, MessageSquareText, Mic2, Printer, RotateCcw, Save, ShieldCheck, Sparkles, Target, Upload, UserRound, Volume2, X } from 'lucide-react';
